CREATE TABLE customers(id TEXT PRIMARY KEY,name TEXT NOT NULL,active INTEGER NOT NULL DEFAULT 1 CHECK(active IN (0,1)),revision INTEGER NOT NULL DEFAULT 0,created INTEGER NOT NULL);
CREATE TABLE customer_plates(plate TEXT PRIMARY KEY,customer_id TEXT NOT NULL REFERENCES customers(id));
CREATE TABLE service_charges(id TEXT PRIMARY KEY,stay_id TEXT UNIQUE REFERENCES stays(id),monthly_id TEXT UNIQUE REFERENCES monthly(id),customer_id TEXT REFERENCES customers(id),total INTEGER NOT NULL CHECK(typeof(total)='integer' AND total>=0),lines TEXT NOT NULL CHECK(json_valid(lines)),actor TEXT NOT NULL,created INTEGER NOT NULL);
CREATE INDEX service_charges_customer ON service_charges(customer_id,created);
CREATE TABLE settlements(id TEXT PRIMARY KEY,total INTEGER NOT NULL CHECK(typeof(total)='integer' AND total>0),lines TEXT NOT NULL CHECK(json_valid(lines)),actor TEXT NOT NULL,paid INTEGER NOT NULL);
CREATE INDEX settlements_paid ON settlements(paid);
CREATE TABLE charge_allocations(payment_id TEXT NOT NULL REFERENCES settlements(id),charge_id TEXT NOT NULL REFERENCES service_charges(id),cents INTEGER NOT NULL CHECK(typeof(cents)='integer' AND cents>0),PRIMARY KEY(payment_id,charge_id));
CREATE INDEX charge_allocations_charge ON charge_allocations(charge_id);
CREATE TABLE event_sessions(id TEXT PRIMARY KEY,business_date TEXT NOT NULL,starts INTEGER NOT NULL,ends INTEGER NOT NULL CHECK(ends>starts),state TEXT NOT NULL CHECK(state IN ('active','ended','cancelled')),catalog TEXT NOT NULL CHECK(json_valid(catalog)),created INTEGER NOT NULL,actor TEXT NOT NULL);
CREATE UNIQUE INDEX one_event_date ON event_sessions(business_date) WHERE state<>'cancelled';
CREATE INDEX event_sessions_end ON event_sessions(ends);
CREATE TRIGGER immutable_settlement_update BEFORE UPDATE ON settlements BEGIN SELECT RAISE(ABORT,'OESTE_IMMUTABLE_PAYMENT'); END;
CREATE TRIGGER immutable_charge_update BEFORE UPDATE ON service_charges BEGIN SELECT RAISE(ABORT,'OESTE_IMMUTABLE_CHARGE'); END;
CREATE TRIGGER immutable_allocation_update BEFORE UPDATE ON charge_allocations BEGIN SELECT RAISE(ABORT,'OESTE_IMMUTABLE_PAYMENT'); END;
CREATE TRIGGER immutable_settlement_delete BEFORE DELETE ON settlements WHEN NOT EXISTS(SELECT 1 FROM maintenance_reset_gate g JOIN operations o ON o.id=g.operation_id AND o.kind='delivery-reset' JOIN users u ON u.id=g.actor_id AND u.role='admin' AND u.active=1 WHERE o.user_id=u.id AND EXISTS(SELECT 1 FROM meta WHERE id='sourceKind' AND value='synthetic') AND EXISTS(SELECT 1 FROM meta WHERE id='authority' AND value='cloud-test')) BEGIN SELECT RAISE(ABORT,'OESTE_IMMUTABLE_PAYMENT'); END;
CREATE TRIGGER immutable_charge_delete BEFORE DELETE ON service_charges WHEN NOT EXISTS(SELECT 1 FROM maintenance_reset_gate g JOIN operations o ON o.id=g.operation_id AND o.kind='delivery-reset' JOIN users u ON u.id=g.actor_id AND u.role='admin' AND u.active=1 WHERE o.user_id=u.id AND EXISTS(SELECT 1 FROM meta WHERE id='sourceKind' AND value='synthetic') AND EXISTS(SELECT 1 FROM meta WHERE id='authority' AND value='cloud-test')) BEGIN SELECT RAISE(ABORT,'OESTE_IMMUTABLE_CHARGE'); END;
CREATE TRIGGER immutable_allocation_delete BEFORE DELETE ON charge_allocations WHEN NOT EXISTS(SELECT 1 FROM maintenance_reset_gate g JOIN operations o ON o.id=g.operation_id AND o.kind='delivery-reset' JOIN users u ON u.id=g.actor_id AND u.role='admin' AND u.active=1 WHERE o.user_id=u.id AND EXISTS(SELECT 1 FROM meta WHERE id='sourceKind' AND value='synthetic') AND EXISTS(SELECT 1 FROM meta WHERE id='authority' AND value='cloud-test')) BEGIN SELECT RAISE(ABORT,'OESTE_IMMUTABLE_PAYMENT'); END;
